INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_955', 'mbe', '955', '715', '1992', '', '445', '', 'Congress enacts a law providing that all disagreements between the United States and a state over federal grant-in-aid funds shall be settled by the filing of a suit in the federal district court in the affected state. "The judgment of that federal court shall be transmitted to the head of the federal agency dispensing such funds who, if satisfied that the judgment is fair and lawful, shall execute the judgment according to its terms." This law is', 'constitutional, because disagreements over federal grant-in-aid funds necessarily involve federal questions within the judicial power of the United States.', 'constitutional, because the spending of federal monies necessarily includes the authority to provide for the effective settlement of disputes involving them.', 'unconstitutional, because it vests authority in the federal court to determine a matter prohibited to it by the Eleventh Amendment.', 'unconstitutional, because it vests authority in a federal court to render an advisory opinion.', 'D', 'Federal courts cannot issue advisory opinions because of the Constitution''s case-or-controversy requirement.', 'mbe_731', 0, '445'),
('mbe_957', 'mbe', '957', '717', '1992', '', '447', '', 'In a contract suit by Perez against Drake, each of the following is an accepted method of authenticating Drake''s signature on a document offered by Perez EXCEPT:', 'A non-expert who, in preparation for trial, has familiarized himself with Drake''s usual signature testifies that, in his opinion, the questioned signature is genuine.', 'The jury, without the assistance of an expert, compares the questioned signature with an admittedly authentic sample of Drake''s handwriting.', 'A witness offers proof that the signature is on a document that has been in existence for at least 20 years, that was in a place where it would be if it was authentic, and that has no suspicious circumstances surrounding it.', 'A witness testifies that Drake admitted that the signature is his.', 'A', 'the opinion of a qualified expert on a question about the authenticity of a disputed signature or writing generally may be received in evidence and weighed by the trier of facts, even if it is contrary to fact testimony. Testimony has been held admissible as to the authenticity of—
— signatures on agreements,
— promissory notes,
— checks,
— and wills,
— letters,
— a page in a corporate minute book,
— a treasury note.', 'mbe_732', 0, '447'),
('mbe_958', 'mbe', '958', '718', '1992', '', '448', '', 'For a valuable consideration, Amato, the owner of Riveracre, signed and gave to Barton a duly executed instrument that provided as follows: "The grantor may or may not sell Riveracre during her lifetime, but at her death, or if she earlier decides to sell, the property will be offered to Barton at $500 per acre. Barton shall exercise this right, if at all, within 60 days of receipt of said offer to sell." Barton recorded the instrument. The instrument was not valid as a will. Is Barton''s right under the instrument valid?', 'Yes, because the instrument is recorded.', 'Yes, because Barton''s right to purchase will vest or fail within the period prescribed by the Rule Against Perpetuities.', 'No, because Barton''s right to purchase is a restraint on the owner''s power to make a testamentary disposition.', 'No, because Barton''s right to purchase is an unreasonable restraint on alienation.', 'B', 'Various factors bear on the reasonableness of a restraint on alienation.  Factors tending to support a finding of reasonableness include:
1. the one imposing the restraint has some interest in land which he is seeking to protect by the enforcement of the restraint;
2. the restraint is limited in duration;
3. the enforcement of the restraint accomplishes a worthwhile purpose;
**168 4. the type of conveyances prohibited are ones not likely to be employed to any substantial degree by the one restrained;
5. the number of persons to whom alienation is prohibited is small;
6. the one upon whom the restraint is imposed is a charity.
[Restatement of Property § 406, comment i (1944) (citation omitted); accord Restatement (Third) of Property: Servitudes § 3.4, comment c (2000).]', 'mbe_733', 0, '448'),
('mbe_960', 'mbe', '960', '720', '1992', '', '450', 'Dunbar and Balcom went into a drugstore, where Dunbar reached into the cash register and took out $200. Stone, the owner of the store, came out of a back room, saw what had happened, and told Dunbar to put the money back. Balcom then took a revolver from under his coat and shot and killed Stone.', 'If Dunbar is prosecuted for murder on the basis of felony murder and the jury believes her claim, she should be found', 'guilty, because her companion, Balcom, committed a homicide in the course of a felony.', 'guilty, because her taking Balcom with her to the store created the risk of death that occurred during the commission of a felony.', 'not guilty, because she did not know that Balcom was armed and thus did not have the required mental state for felony murder.', 'not guilty, because she believed she was entitled to the money and thus did not intend to steal.', 'D', 'Under the felony-murder rule, a strict causal or temporal relationship between the felony and the murder is not required; what is required is proof beyond a reasonable doubt that the felony and murder were part of one continuous transaction. (People v. Cavitt (2004) 33 Cal.4th 187, 207, 14 Cal.Rptr.3d 281, 91 P.3d 222.)', 'mbe_734', 0, '450'),
('mbe_961', 'mbe', '961', '720', '1992', '', '451', 'Dunbar and Balcom went into a drugstore, where Dunbar reached into the cash register and took out $200. Stone, the owner of the store, came out of a back room, saw what had happened, and told Dunbar to put the money back. Balcom then took a revolver from under his coat and shot and killed Stone.', 'If Dunbar is prosecuted for murder on the basis of being an accessory to Balcom in committing a murder and the jury believes her claim, she should be found', 'guilty, because in firing the shot Balcom was trying to help her.', 'guilty, because she and Balcom were acting in concert in a dangerous under- taking.', 'not guilty, because she had no idea that Balcom was armed and she did not plan to use force.', 'not guilty, because she was exercising self- help and did not intend to steal.', 'C', 'Accessorial liability requires only that defendant, acting with the mental culpability required for the commission of the crime, intentionally aid another in the conduct constituting the offense” (People v. Chapman, 30 A.D.3d 1000, 1001, 816 N.Y.S.2d 256, lv. denied 7 N.Y.3d 811, 822 N.Y.S.2d 486, 855 N.E.2d 802 [internal quotation marks omitted]; see § 20.00).', 'mbe_735', 0, '451'),
('mbe_963', 'mbe', '963', '722', '1992', '', '453', '', 'Acorp and Beeco are companies that each manufacture pesticide X. Their plants are located along the same river. During a specific 24-hour period, each plant discharged pesticide into the river. Both plants were operated negligently and such negligence caused the discharge of the pesticide into the river. Landesmann operated a cattle ranch downstream from the plants of Acorp and Beeco. Landesmann''s cattle drank from the river and were poisoned by the pesticide. The amount of the discharge from either plant alone would not have been sufficient to cause any harm to Landesmann''s cattle. If Landesmann asserts a claim against Acorp and Beeco, what, if anything, will Landesmann recover?', 'Nothing, because neither company discharged enough pesticide to cause harm to Landesmann''s cattle.', 'Nothing, unless Landesmann can establish how much pesticide each plant discharged.', 'One-half of Landesmann''s damages from each company.', 'The entire amount of Landesmann''s damages, jointly and severally, from the two companies.', 'D', 'The rule of joint and several liability applies when two or more tortfeasors'' actions combine to cause a plaintiff''s injuries. Rozevink v. Faris, 342 N.W.2d 845, 847 (Iowa 1983). Prior to the adoption of our comparative fault act, the common-law rule required each joint tortfeasor to be jointly and severally liable for a plaintiff''s entire loss. Id. at 850, modified in part by statute as stated in Johnson v. Junkmann, 395 N.W.2d 862, 867 (Iowa 1986).', 'mbe_736', 0, '453'),
('mbe_964', 'mbe', '964', '723', '1992', '', '454', '', 'Paulsen sued Daly for nonpayment of a personal loan to Daly, as evidenced by Daly''s promissory note to Paulsen. Paulsen called Walters to testify that he knows Daly''s handwriting and that the signature on the note is Daly''s. On direct examination, to identify himself, Walters gave his name and address and testified that he had been employed by a roofing company for seven years. During presentation of Daly''s case, Daly called Wilson to testify that she is the roofing company''s personnel manager and that she had determined, by examining the company''s employment records, that Walters had worked there only three years. The trial judge should rule that Wilson''s testimony is', 'inadmissible, because it is not the best evidence.', 'inadmissible, because it is impeachment on a collateral question.', 'admissible as evidence of a regularly conducted activity.', 'admissible as tending to impeach Walters'' credibility.', 'B', 'Ordinarily, impeachment evidence is admissible if it is relevant to undermining the credibility of the witness being impeached. See State v. Turecek, 456 N.W.2d 219, 224 (Iowa 1990).', 'mbe_737', 0, '454'),
('mbe_966', 'mbe', '966', '725', '1992', '', '456', 'Cycle Company manufactured a bicycle that it sold to Bike Shop, a retail bicycle dealer, which in turn sold it to Roth. Shortly thereafter, while Roth was riding the bicycle along a city street, he saw a traffic light facing him turn from green to yellow. He sped up, hoping to cross the intersection before the light turned red. However, Roth quickly realized that he could not do so and applied the brake, which failed. To avoid the traffic that was then crossing in front of him, Roth turned sharply to his right and onto the sidewalk, where he struck Perez, a pedestrian. Both Perez and Roth sustained injuries.', 'If Roth asserts a claim against Bike Shop based on strict liability in tort, will Roth prevail?', 'Yes, if the brake failed because of a defect present when the bicycle left the factory of Cycle Company.', 'Yes, because the brake failed while Roth was riding the bicycle.', 'No, if Roth contributed to his own injury by speeding up.', 'No, if Bike Shop carefully inspected the bicycle before selling it.', 'A', '“[a] manufacturer may be held strictly liable for placing a defective product on the market if the plaintiff''s injury results from a reasonably foreseeable use of the product.” Saller v. Crown Cork & Seal Co., Inc., 187 Cal.App.4th 1220, 1231, 115 Cal.Rptr.3d 151 (2010).', 'mbe_738', 0, '456'),
('mbe_967', 'mbe', '967', '725', '1992', '', '457', 'Cycle Company manufactured a bicycle that it sold to Bike Shop, a retail bicycle dealer, which in turn sold it to Roth. Shortly thereafter, while Roth was riding the bicycle along a city street, he saw a traffic light facing him turn from green to yellow. He sped up, hoping to cross the intersection before the light turned red. However, Roth quickly realized that he could not do so and applied the brake, which failed. To avoid the traffic that was then crossing in front of him, Roth turned sharply to his right and onto the sidewalk, where he struck Perez, a pedestrian. Both Perez and Roth sustained injuries.', 'If Perez asserts a claim based on negligence against Cycle Company and if it is found that the brake failure resulted from a manufacturing defect in the bicycle, will Perez prevail?', 'Yes, because Cycle Company placed a defective bicycle into the stream of commerce.', 'Yes, if the defect could have been discovered through the exercise of reasonable care by Cycle Company.', 'No, because Perez was not a purchaser of the bicycle.', 'No, if Roth was negligent in turning onto the sidewalk.', 'B', 'To prove a manufacturing defect claim under Florida law, a plaintiff must prove that 1) the product was defective, 2) *1344 the defect existed at the time the product left the defendant-manufacturer''s control, and 3) the defect proximately caused the plaintiff''s injuries. See, e.g., Wolicki-Gables v. Arrow Int''l, Inc., 641 F. Supp. 2d 1270, 1285 (M.D. Fla. 2009) (citing Colville v. Pharmacia & Upjohn Co., 565 F. Supp. 2d 1314, 1320 (N.D. Fla. 2008))', 'mbe_739', 0, '457'),
('mbe_969', 'mbe', '969', '727', '1992', '', '459', 'On October 1, Toy Store, Inc., entered into a written contract with Fido Factory, Inc., for the purchase at $20 per unit of 1,000 mechanical dogs, to be specially manufactured by Fido according to Toy Store''s specifications. Fido promised to deliver all of the dogs "not later than November 15, for the Yule shopping season," and Toy Store promised to pay the full $20,000 price upon delivery. In order to obtain operating funds, Fido as borrower entered into a written loan agreement on October 5 with the High Finance Company. In relevant part, this agreement recited, "Fido Factory hereby transfers and assigns to High Finance its (Fido Factory''s) October 1 mechanical dog contract with Toy Store, as security for a 50-day loan of $15,000, the advance and receipt of which are hereby acknowledged by Fido Factory." No copy of this agreement, or statement relating to it, was filed in an office of public record. On October 15, Fido notified Toy Store, "We regret to advise that our master shaft burned out last night because our night supervisor let the lubricant level get too low. We have just fired the supervisor, but the shaft cannot be repaired or replaced until about January 1. We can guarantee delivery of your order, however, not later than January 20." Toy Store rejected this proposal as unacceptable and immediately contracted with the only other available manufacturer to obtain the 1,000 dogs at $30 per unit by November 15.', 'For this question only, assume that on November 1, Toy Store sues Fido for damages and alleges the above facts, except those relating to the Fido-High Finance loan agreement. Upon Fido''s motion to dismiss the complaint, the court should', 'sustain the motion, because Fido on October 15 stated its willingness, and gave assurance of its ability, to perform the contract in January.', 'sustain the motion, because Toy Store''s lawsuit is premature in any case until after November 15.', 'deny the motion, because Toy Store''s complaint alleges an actionable tort by Fido.', 'deny the motion, because Toy Store''s complaint alleges an actionable breach of contract by Fido.', 'D', 'To properly plead breach of contract, the complaint must identify the specific provision of the contract allegedly breached by a defendant.', 'mbe_740', 0, '459'),
('mbe_970', 'mbe', '970', '727', '1992', '', '460', 'On October 1, Toy Store, Inc., entered into a written contract with Fido Factory, Inc., for the purchase at $20 per unit of 1,000 mechanical dogs, to be specially manufactured by Fido according to Toy Store''s specifications. Fido promised to deliver all of the dogs "not later than November 15, for the Yule shopping season," and Toy Store promised to pay the full $20,000 price upon delivery. In order to obtain operating funds, Fido as borrower entered into a written loan agreement on October 5 with the High Finance Company. In relevant part, this agreement recited, "Fido Factory hereby transfers and assigns to High Finance its (Fido Factory''s) October 1 mechanical dog contract with Toy Store, as security for a 50-day loan of $15,000, the advance and receipt of which are hereby acknowledged by Fido Factory." No copy of this agreement, or statement relating to it, was filed in an office of public record. On October 15, Fido notified Toy Store, "We regret to advise that our master shaft burned out last night because our night supervisor let the lubricant level get too low. We have just fired the supervisor, but the shaft cannot be repaired or replaced until about January 1. We can guarantee delivery of your order, however, not later than January 20." Toy Store rejected this proposal as unacceptable and immediately contracted with the only other available manufacturer to obtain the 1,000 dogs at $30 per unit by November 15.', 'For this question only, assume that by November 16, Fido, without legal excuse, has delivered no dogs, and that Toy Store has brought an action against Fido. In an action brought on November 16 by Toy Store against High Finance Company on account of Fido''s default, Toy Store can recover', 'nothing, because the October 5 assignment by Fido to High Finance of Fido''s contract with Toy Store was only an assignment for security.', 'nothing, because no record of the October 5 transaction between Fido and High Finance was publicly filed.', '$10,000 in damages, because Toy Store was a third-party intended beneficiary of the October 5 transaction between Fido and High Finance.', '$10,000 in damages, because the October 5 transaction between Fido and High Finance effected, with respect to Toy Store as creditor, a novation of debtors.', 'A', 'An assignment is the transfer of some identifiable property, claim, or right from the assignor to the assignee.[i] In DeBenedictis v. Hagen, 77 Wn. App. 284 (Wash. Ct. App. 1995), the court distinguishes between two kinds of assignments: assignment by a creditor/assignor of his/her claim against a debtor in such a way as to effect a complete sale of the claim.
assignment by a creditor/assignor of his or her claim against a debtor for purposes of collection.
In Wash. State Bar Ass’n v. Merchants’ Rating & Adjusting Co., 183 Wash. 611 (Wash. 1935), the court held that an assignment for the purpose of collection is an assignment for a valuable consideration.  
An assignment for the purposes of collection does not transfer the beneficial ownership to the assignee but vests legal title in the assignee, empowers the assignee to collect, and permits the debtor to discharge himself by making payment to the assignee.', 'mbe_741', 0, '460'),
('mbe_971', 'mbe', '971', '728', '1992', '', '461', '', 'A 10-lot subdivision was approved by the proper governmental authority. The authority''s action was pursuant to a map filed by Diaz, which included an undesignated parcel in addition to the 10 numbered lots. The undesignated parcel is differently shaped and somewhat larger than any one of the numbered lots. Subdivision building restrictions were imposed on "all the lots shown on said map." Diaz contracts to sell the unnumbered lot, described by metes and bounds, to Butts. Is title to the parcel marketable?', 'Yes, because the undesignated parcel is not a lot to which the subdivision building restrictions apply.', 'Yes, because the undesignated parcel is not part of the subdivision.', 'No, because the undesignated parcel has never been approved by the proper governmental authority.', 'No, because the map leaves it uncertain as to whether the unnumbered lot is subject to the building restrictions.', 'D', 'Marketable title is “[a] title that a reasonable buyer would accept because it appears to lack any defect and to cover the entire property that the seller has purported to sell....—Also termed good title; merchantable title; clear title.” Id. at 1523. “A ‘marketable title’ is one free from reasonable doubt in law or fact as to its validity.” Pack v. Newman, 232 N.C. 397, 400, 61 S.E.2d 90, 92 (1950) (citation omitted). Good title is defined as “1. A title that is legally valid or effective. 2. See clear title (1). 3. See marketable title.” Black''s at 1523.', 'mbe_742', 0, '461'),
('mbe_972', 'mbe', '972', '729', '1992', '', '462', '', 'A state statute requires the permanent removal from parental custody of any child who has suffered "child abuse." That term is defined to include "corporal punishment of any sort." Zeller very gently spanks his six-year-old son on the buttocks whenever he believes that spanking is necessary to enforce discipline on him. Such a spanking occurs not more than once a month and has never physically harmed the child. The state files suit under the statute to terminate Zeller''s parental rights solely because of these spankings. Zeller defends only on the ground that the statute in question is unconstitutional as applied to his admitted conduct. In light of the nature of the rights involved, which of the following is the most probable burden of persuasion on this constitutional issue?', 'The state has the burden of persuading the court that the application of this statute to Zeller is necessary to vindicate an important state interest.', 'The state has the burden of persuading the court that the application of this statute to Zeller is rationally related to a legitimate state interest.', 'Zeller has the burden of persuading the court that the application of this statute to him is not necessary to vindicate an important state interest.', 'Zeller has the burden of persuading the court that the application of this statute to him is not rationally related to a legitimate state interest.', 'A', 'Party challenging the constitutionality of a statute bears the burden of proving that the statute and its application are unconstitutional beyond a reasonable doubt.', 'mbe_743', 0, '462'),
('mbe_974', 'mbe', '974', '731', '1992', '', '464', '', 'In March, when Ohm was 17, Stereo delivered to Ohm a television set. At that time Ohm agreed in writing to pay $400 for the set on July 1 when he would reach his 18th birthday. Eighteen is the applicable statutory age of majority, and on that date Ohm was to receive the proceeds of a trust. On July 1, when the reasonable value of the television set was $250, Ohm sent Stereo a signed letter stating, "I''ll only pay you $300; that is all the set is worth." In an action against Ohm for money damages on July 2, what is the maximum amount that Stereo will be entitled to recover?', 'Nothing', '$250, the reasonable value of the set', '$300, the amount Ohm promised to pay in his letter of July 1', '$400, the original sale price', 'C', 'Damages recoverable for breach of contract are only those caused by the breach.', 'mbe_744', 0, '464'),
('mbe_975', 'mbe', '975', '732', '1992', '', '465', '', 'Dray was prosecuted for bank robbery. At trial, the bank teller, Wall, was unable to identify Dray, now bearded, as the bank robber. The prosecutor then showed Wall a group of photographs, and Wall testified that she had previously told the prosecutor that the middle picture (concededly a picture of Dray before he grew a beard) was a picture of the bank robber. Wall''s testimony is', 'inadmissible, because it is hearsay, not within any exception.', 'inadmissible, because it is a violation of Dray''s right of confrontation.', 'admissible as prior identification by the witness.', 'admissible as past recollection recorded.', 'C', 'Evidence of a statement previously made by a witness is not made inadmissible by the hearsay rule if the statement would have been admissible if made by him while testifying and:
(a) The statement is an identification of a party or another as a person who participated in a crime or other occurrence;
(b) The statement was made at a time when the crime or other occurrence was fresh in the witness'' memory; and
(c) The evidence of the statement is offered after the witness testifies that he made the identification and that it was a true reflection of his opinion at that time.', 'mbe_745', 0, '465'),
('mbe_976', 'mbe', '976', '733', '1992', '', '466', '', 'Which of the following is LEAST likely to be the underlying felony in a prosecution for felony murder?', 'Arson.', 'Manslaughter.', 'Attempted rape.', 'Burglary.', 'B', 'Manslaughter is “the taking of human life by an act not justified in law, but without malice aforethought which is necessary *438 to constitute murder.” Commonwealth v. Campbell, 352 Mass. 387, 396–397, 226 N.E.2d 211 (1967). Voluntary manslaughter is defined as a killing committed in “a sudden transport of passion or heat of blood, upon reasonable **78 provocation and without malice, or upon sudden combat.” Id., quoting Commonwealth v. Bouvier, 316 Mass. 489, 494, 55 N.E.2d 913 (1944). “Sudden combat” is “one of the events which may provoke the perturbation of mind that can end in a killing without malice.” Commonwealth v. Peters, 372 Mass. 319, 324, 361 N.E.2d 1277 (1977). Voluntary manslaughter may be based on a theory of the excessive use of force in self-defense. Commonwealth v. Walden, 380 Mass. 724, 729, 405 N.E.2d 939 (1980), citing Commonwealth v. Kendrick, 351 Mass. 203, 211–212, 218 N.E.2d 408 (1966).', 'mbe_746', 0, '466'),
('mbe_977', 'mbe', '977', '734', '1992', '', '467', 'Morris was driving north on an interstate highway at about 50 miles per hour when a tractor-trailer rig, owned and driven by Dixon, passed her. The tractor was pulling a refrigerated meat trailer fully loaded with beef carcasses hanging freely from the trailer ceiling. When Dixon cut back in front of Morris, the shifting weight of the beef caused the trailer to overturn. Morris was unable to avoid a collision with the overturned trailer and was injured. The trailer had been manufactured by Trailco. A number of truckers had complained to Trailco that the design of the trailer, which allowed the load to swing freely, was dangerous. Dixon knew of the dangerous propensity of the trailer. A restraining device that could be installed in the trailer would prevent the load from shifting and was available at nominal cost. Dixon knew of the restraining device but had not installed it.', 'If Morris asserts a claim based on strict liability tort against Trailco, she will', 'recover unless Morris was negligently driving when the truck overturned.', 'recover, because Dixon''s knowledge of the dangerous propensity of the trailer does not relieve Trailco of liability.', 'not recover, because there was no privity of contract between Morris and Trailco.', 'not recover if Dixon was negligent in failing to install the restraining device in the trailer.', 'B', 'Manufacturers and sellers are strictly liable for injuries caused by unreasonably dangerous products unless an unforeseen alteration by a third party introduced the unsafe condition. See Peterson v. Lou Bachrodt Chevrolet Co., 61 Ill.2d 17, 329 N.E.2d 785, 786–87 (1975); Brdar v. Cottrell, Inc., 372 Ill.App.3d 690, 311 Ill.Dec. 99, 867 N.E.2d 1085, 1099 (2007); Monreal v. Waterbury–Farrel Foundry & Mach. Co., 269 Ill.App.3d 841, 207 Ill.Dec. 250, 646 N.E.2d 1337, 1340 (1995); Wiedemann v. Indus. Erectors, Inc., 137 Ill.App.3d 47, 91 Ill.Dec. 504, 483 N.E.2d 990, 997–98 (1985).', 'mbe_747', 0, '467'),
('mbe_978', 'mbe', '978', '734', '1992', '', '468', 'Morris was driving north on an interstate highway at about 50 miles per hour when a tractor-trailer rig, owned and driven by Dixon, passed her. The tractor was pulling a refrigerated meat trailer fully loaded with beef carcasses hanging freely from the trailer ceiling. When Dixon cut back in front of Morris, the shifting weight of the beef caused the trailer to overturn. Morris was unable to avoid a collision with the overturned trailer and was injured. The trailer had been manufactured by Trailco. A number of truckers had complained to Trailco that the design of the trailer, which allowed the load to swing freely, was dangerous. Dixon knew of the dangerous propensity of the trailer. A restraining device that could be installed in the trailer would prevent the load from shifting and was available at nominal cost. Dixon knew of the restraining device but had not installed it.', 'If Morris asserts a claim for her injuries against Dixon, she will', 'prevail if the use of a restraining device would have prevented the trailer from overturning.', 'prevail, because Dixon is strictly liable to Morris for injuries resulting from defects in the trailer.', 'not prevail unless Dixon was driving in a negligent manner at the time Morris was injured.', 'not prevail, because Dixon was not the manufacturer or seller of the trailer.', 'A', 'If a car accident is caused by a defective condition that the driver knew or should have known of, the driver’s failure to maintain their vehicle in a safe condition may constitute negligence, and ultimately hold the driver liable for damages to injured car accident victims.', 'mbe_748', 0, '468'),
('mbe_979', 'mbe', '979', '735', '1992', '', '469', '', 'Fernwood Realty Company developed a residential development, known as the Fernwood Development, which included single-family dwellings, townhouses, and high-rise apartments for a total of 25,000 dwelling units. Included in the deed to each unit was a covenant under which the grantee and the grantee''s "heirs and assigns" agreed to purchase electrical power from only a plant Fernwood promised to build and maintain within the development. Fernwood constructed the plant and the necessary power lines. The plant did not supply power outside the development. An appropriate and fair formula was used to determine price. After constructing and selling 12,500 of the units, Fernwood sold its interest in the development to Gaint Realty Investors. Gaint operated the power plant and constructed and sold the remaining 12,500 units. Each conveyance from Gaint contained the same covenant relating to electrical power that Fernwood had included in the 12,500 conveyances it had made. Page bought a dwelling unit from Olm, who had purchased it from Fernwood. Subsequently, Page, whose lot was along the boundary of the Fernwood Development, ceased buying electrical power from Gaint and began purchasing power from General Power Company, which provided such service in the area surrounding the Fernwood Development. Both General Power and Gaint have governmental authorization to provide electrical services to the area. Gaint instituted an appropriate action against Page to enjoin her from obtaining electrical power from General Power. If judgment is for Page, it most likely will be because', 'the covenant does not touch and concern the land.', 'the mixture of types of residential units is viewed as preventing one common development scheme.', 'the covenant is a restraint on alienation.', 'there is no privity of estate between Page and Gaint.', 'A', 'A covenant touches and concerns the land when it affects the nature, quality, or value of what is conveyed, or if it either renders the grantor''s interest in the land less valuable or renders the grantee''s interest more valuable. Westland Oil Dev. Corp., 637 S.W.2d at 911.', 'mbe_749', 0, '469'),
('mbe_980', 'mbe', '980', '736', '1992', '', '470', '', 'Congress passes an Energy Conservation Act. The act requires all users of energy in this country to reduce their consumption by a specified percentage, to be set by a presidential executive order. The act sets forth specific standards the President must use in setting the percentage and detailed procedures to be followed. The provision that allows the President to set the exact percentage is probably', 'constitutional, because it creates a limited administrative power to implement the statute.', 'constitutional, because inherent executive powers permit such action even without statutory authorization.', 'unconstitutional as an undue delegation of legislative power to the executive.', 'unconstitutional, because it violates the due process clause of the Fifth Amendment.', 'A', 'Congress has “wide latitude in meeting the intelligible *1020 principle requirement ... [because] ‘Congress simply cannot do its job absent an ability to delegate power under broad general directives.’ ” Id. (quoting Mistretta v. United States, 488 U.S. 361, 372, 109 S.Ct. 647, 102 L.Ed.2d 714 (1989)). “Congress fails to give sufficient guidance in its delegations only if it ‘would be impossible in a proper proceeding to ascertain whether the will of Congress has been obeyed.’ ” Id. at 796 (quoting Yakus v. United States, 321 U.S. 414, 426, 64 S.Ct. 660, 88 L.Ed. 834 (1944)).', 'mbe_750', 0, '470'),
('mbe_981', 'mbe', '981', '737', '1992', '', '471', '', 'Ortega owned Blackacre in fee simple and by his will specifically devised Blackacre as follows: "To my daughter, Eugenia, her heirs and assigns, but if Eugenia dies survived by a husband and a child or children, then to Eugenia''s husband during his lifetime with remainder to Eugenia''s children, their heirs and assigns. Specifically provided, however, that if Eugenia dies survived by a husband and no child, Blackacre is specifically devised to my nephew, Luis, his heirs and assigns." While Ortega''s will was in probate, Luis quitclaimed all interest in Blackacre to Eugenia''s husband, Jos&. Three years later, Eugenia died, survived by Jos& but no children. Eugenia left a will devising her interest in Blackacre to Jos&. The only applicable statute provides that any interest in land is freely alienable. Luis instituted an appropriate action against Jos& to establish title to Blackacre. Judgment should be for', 'Luis, because his quitclaim deed did not transfer his after-acquired title.', 'Luis, because Jos& took nothing under Ortega''s will.', 'Jos&, because Luis had effectively conveyed his interest to Jos&.', 'Jos&, because the doctrine of after-acquired title applies to a devise by will.', 'C', 'The doctrine of after-acquired title does not apply to a void conveyance. See Pascoe v. Keuhnast, 642 S.W.2d 37, 40 (Tex. App.—Waco 1982, writ ref''d n.r.e.) (declining to apply doctrine of after-acquired title to a purported conveyance by wife without husband’s joinder because said conveyance was void); see also Fort Apache Energy, Inc. v. Resaca Res., LLC, No. 09-14-00325-CV, 2016 WL 637985, at *7 (Tex. App.—Beaumont Feb. 18, 2016, no pet.) (mem. op.).', 'mbe_751', 0, '471'),
('mbe_982', 'mbe', '982', '738', '1992', '', '472', '', 'Duncan was charged with aggravated assault. At trial Duncan did not testify; however, he sought to offer opinion evidence of his good character for truth and veracity. This testimony should be', 'admitted, because a criminal defendant is entitled to offer evidence of his good character.', 'admitted, because a party''s credibility is necessarily in issue.', 'excluded, because character is not admissible to prove conduct in conformity therewith.', 'excluded, because it is evidence of a trait not pertinent to the case.', 'D', 'Generally, opinion testimony is not a proper method of admitting evidence regarding character traits. In re J.M., 226 Ill.App.3d 681, 685, 168 Ill.Dec. 701, 589 N.E.2d 1101, 1104 (1992).', 'mbe_752', 0, '472'),
('mbe_983', 'mbe', '983', '739', '1992', '', '473', '', 'Alford was a suspect in a homicide committed during a robbery of a liquor store. Barber was a friend of Alford. Police telephoned Barber and asked if he would help locate Alford. Barber agreed and met the police officers at headquarters later that night. After a discussion during which police asked questions about Alford and the homicide, Barber said that he wanted to get something "off his chest" and advised the officers that he was in on the robbery but that Alford had shot the owner of the store without his permission or prior knowledge. The officers then for the first time gave Barber his Miranda warnings. Barber was indicted for felony murder. He moved to prevent the introduction of his statement into evidence. His motion should be', 'granted, because Barber was effectively in custody and entitled to receive Miranda warnings at the beginning of the discussion.', 'granted, because Barber''s rights to counsel and to due process were violated by the interrogation at police headquarters.', 'denied, because his statement was freely and voluntarily given and he was not entitled to Miranda warnings.', 'denied, because by visiting headquarters voluntarily, Barber waived his right to receive Miranda warnings at the beginning of the discussion.', 'C', '“[W]e review de novo a [circuit] court''s ruling on the question whether a defendant knowingly, intelligently, and voluntarily waived Miranda rights.” State v. Tuttle, 2002 S.D. 94, ¶ 6, 650 N.W.2d 20, 25. “When a person is in the custody of law enforcement and law enforcement intends to perform a custodial interrogation of that person, they are required to read them their Miranda rights.” State v. Lewandowski, 2019 S.D. 2, ¶ 20, 921 N.W.2d 915, 920. A waiver need not be explicit, but “[t]o prove a valid waiver, the State must show that (1) the relinquishment of the defendant''s rights was voluntary and (2) the defendant was fully aware that those rights were being waived and of the consequences of waiving them.” Tuttle, 2002 S.D. 94, ¶ 9, 650 N.W.2d at 26. The State must prove the validity of the waiver by a preponderance of the evidence. Id. ¶ 8', 'mbe_753', 0, '473'),
('mbe_984', 'mbe', '984', '740', '1992', '', '474', '', 'The federal government has complete jurisdiction over certain parkland located within the state of Plains. To conserve the wildlife that inhabits that land, the federal government enacts a statute forbidding all hunting of animals in the federal park. That statute also forbids the hunting of animals that have left the federal park and have entered the state of Plains. Hanson has a hunting license from the state of Plains authorizing him to hunt deer anywhere in the state. On land within the state of Plains located adjacent to the federal park, Hanson shoots a deer he knows has recently left the federal land. Hanson is prosecuted for violating the federal hunting law. The strongest ground supporting the constitutionality of the federal law forbidding the hunting of wild animals that wander off federal property is that', 'this law is a necessary and proper means of protecting United States property.', 'the animals are moving in the stream of interstate commerce.', 'the police powers of the federal government encompass protection of wild animals.', 'shooting wild animals is a privilege, not a right.', 'A', 'Under the Necessary and Proper Clause, Congress may take any means “rationally related” to implementing its constitutionally enumerated powers, United States v. Comstock, ––– U.S. ––––, 130 S.Ct. 1949, 1956–57, 176 L.Ed.2d 878 (2010), and hence has authority “to see to it that taxpayer dollars appropriated under [the Spending Clause] are in fact ... not frittered away in graft or on projects undermined when funds are siphoned off.” Sabri, 541 U.S. at 605, 124 S.Ct. at 1946.', 'mbe_754', 0, '474'),
('mbe_985', 'mbe', '985', '741', '1992', '', '475', 'Poe ordered some merchandise from Store. When the merchandise was delivered, Poe decided that it was not what he had ordered, and he returned it for credit. Store refused to credit Poe''s account, continued to bill him, and, after 90 days, turned the account over to Kane, a bill collector, for collection. Kane called at Poe''s house at 7 p.m. on a summer evening while many of Poe''s neighbors were seated on their porches. When Poe opened the door, Kane, who was standing just outside the door, raised an electrically amplified bullhorn to his mouth. In a voice that could be heard a block away, Kane called Poe a "deadbeat" and asked him when he intended to pay his bill to Store. Poe, greatly angered, slammed the door shut. The door struck the bullhorn and jammed it forcibly against Kane''s face. As a consequence, Kane lost his front teeth.', 'If Poe asserts a claim based on defamation against Kane, will Poe prevail?', 'Yes, if Kane''s remarks were heard by any of Poe''s neighbors.', 'Yes, because Kane''s conduct was extreme and outrageous.', 'No, unless Kane knew that Poe owed no money to Store.', 'No, unless Poe suffered some special damage.', 'D', '“Defamation is the publication or communication of a false statement of fact that injures someone by adversely affecting the person''s reputation, business, or position—by exposure to public hatred, contempt, ridicule, shame, or disgrace.” Fuchs v. Scripps Howard Broadcasting. Co., 170 Ohio App.3d 679, 2006-Ohio-5349, 868 N.E.2d 1024, ¶ 28 (1st Dist.).', 'mbe_755', 0, '475')
